{
  ORDER: {
    greet: [
      "Brother of the lattice. You walk a true line.",
      "The Architect sees your geometry. Welcome.",
      "Pilgrim with us. The angles know your name."
    ],
    farewell: [
      "May your coordinates remain clean.",
      "Hold the line where the void presses.",
      "Render at the Perfect Sixty, traveler."
    ]
  },
  VOID: {
    greet: [
      "The lattice cracks for you, friend.",
      "You came back to us. The curve recognizes its own.",
      "Initiate. The Architect's eye does not see you here."
    ],
    farewell: [
      "Walk crooked. Walk free.",
      "Tear what they straighten.",
      "The Sphere already broke. We just woke up to it."
    ]
  }
}

{
  // Spoken by faction NPCs when the player has the OPPOSING allegiance
  ORDER: [
    "Heretic of the void. Your line is bent.",
    "The lattice will outlast your kind.",
    "Walk away. The next pilgrim won't ask twice."
  ],
  VOID: [
    "Tool of the Architect. Your coordinates burn.",
    "Straight-walker. You came to the wrong sky.",
    "We see your grid. We will pull it down."
  ]
}

