{
  cyber_city: {
    fogColor:     0x141821,   // fix173: was 0x110030 deep violet — that haze washed distant buildings PURPLE. Now a dark neutral blue-grey that matches the facade so distant towers keep their own colour, not a violet tint.
    // Reduced from 0.00045 to 0.00028. The combination of (a) base 0.00045
    // city density × (b) altitude multiplier at hover/low flight had been
    // making terrain past ~500u invisible, leaving only nearby buildings
    // floating in a foggy void. 0.00028 keeps the cyber atmosphere thick
    // enough for cyberpunk mood without erasing the surrounding terrain.
    fogDensity:   0.000020,  // cyber — atmospheric but crisp
    clearColor:   0x0a0018,
    bloomThreshold: 0.6, bloomStrength: 2.4, bloomRadius: 0.7,
    geometryType: 'box',           // dense rectangular megastructures
    emissiveIntensity: 2.6,        // neon windows
    metalness:    0.4,
    centerScale:  1.0,
    // Dominant color for LOD MID/LOW tiers — what the city looks like as
    // distant silhouettes. Cyber-city reads dark blue-gray since the windows
    // are too small to distinguish at that range.
    distantColor: 0x1a1525
  },
  magical_spires: {
    fogColor:     0xa8d8f0,   // pale sky-blue
    fogDensity:   0.000012,  // magical_spires — crystal clear
    clearColor:   0xe8f4ff,
    bloomThreshold: 0.85, bloomStrength: 1.2, bloomRadius: 0.5,
    geometryType: 'cylinder_cone', // slender tower stalks
    emissiveIntensity: 1.8,
    metalness:    0.15,
    centerScale:  1.4,             // even taller central spires
    // Pulled darker from 0xe6daf0 (pale lavender) — that color rendered
    // nearly white on ICE/GAS planets and made spires invisible against
    // bright skies. Now a deeper smoky violet that reads as solid stone
    // with magical tint regardless of planet palette.
    distantColor: 0x6a5078         // smoky violet marble
  },
  industrial_crucible: {
    fogColor:     0x1a0a05,   // smoke brown-black
    // Reduced from 0.00060 to 0.00035 — same reasoning as cyber_city above.
    // Industrial cities should be smoky but still let you see across the
    // sector. With altitude multiplier this still produces visibly thick
    // ground fog at walk altitude.
    fogDensity:   0.000028,  // industrial — hint of smoke
    clearColor:   0x0d0604,
    bloomThreshold: 0.7, bloomStrength: 1.8, bloomRadius: 0.4,
    geometryType: 'heavy_blocks',  // bulky bunker footprints
    emissiveIntensity: 2.2,        // glowing lava seams
    metalness:    0.7,
    centerScale:  0.7,             // low and oppressive
    distantColor: 0x3a2418         // sooty brown
  },
  medieval_citadel: {
    fogColor:     0xb8a880,   // warm afternoon haze
    fogDensity:   0.000018,  // medieval — open air
    clearColor:   0xd4c8a0,
    bloomThreshold: 0.9, bloomStrength: 0.9, bloomRadius: 0.4,
    geometryType: 'composite_tower', // octagonal keeps
    emissiveIntensity: 1.4,
    metalness:    0.1,
    centerScale:  1.1,
    // Darkened from 0x8a7860 (light tan) to a more saturated weathered
    // stone. Old color was pale enough to blend with snow/sand planets.
    distantColor: 0x5a4938         // deep weathered stone
  }
}

