}
if (typeof window !== 'undefined') window._ceremony = _ceremony;

// fix473: THE FINAL CADENCE -- event-driven final-quest sequencer over the existing
// tesseract/cavern path. Beats 2-4 play on entering the Tesseract (the faceplate
// soundscape shifts per Movement); the drop onto the black mass fires the Threshold;
// entering the caverns fires the Pupil; the Zero-Point holds for the player's choice.
;(function(){
  if (typeof window === 'undefined' || window._FinalCadence) return;
  function cer(o){ try { if (typeof _ceremony==='function') return _ceremony(o); if (window._ceremony) return window._ceremony(o); } catch(e){} }
  function whisper(t){ try { if (typeof showLoreWhisper==='function') return showLoreWhisper(t); if (window.showLoreWhisper) return window.showLoreWhisper(t); } catch(e){} }
  function setFace(f){ try { if (f && typeof audioBridge!=='undefined' && audioBridge && audioBridge.setFace) audioBridge.setFace(f); } catch(e){} }

  var MOVEMENTS = [
    { face:'SOUL',      text:'The Reedfolk line the river here. They do not fear you — every voice that enters the Chord is, to them, Coda returning.' },
    { face:'GAS',       text:'Coda, recovered: “I thought I was chasing a structure. It is chasing nothing. It only holds. Hold long enough and you stop being a traveler and become a note.”' },
    { face:'DNB',       text:'The Dissonant cross your Movement — voices that drifted out of harmony an age ago and call the search a sickness. Not wrong to be afraid. Only wrong to have stopped.' },
    { face:'GLITCHPOP', text:'The Bars come faster now, the Movements shorter. You near the center, where the note is held hardest.' }
  ];

  var BEATS = [
    { face:'BARD', ceremony:{ lore:'THE FIRST BAR — the Long Chord fills your sky, one note sustained since before your kind had a name. Enter, voice, and become part of the song.', root:130.81, wave:'sine', arp:false, fov:12, vol:0.5 }, delay:9000 },
    { movements:MOVEMENTS, gap:7000, delay:2500 },
    { face:'SOUL', ceremony:{ lore:'CODA: “You came. Of course — you are me, a few Verses behind. The Long Chord is not a place; it is an instrument, and there is a Conductor. The sun-line is not a sun — it is a window, and the builder looks back through it. Take this note from me. I am tired of being the end of the piece.”', root:174.61, wave:'sine', arp:false, fov:18, vol:0.55 }, hold:true },
    { face:'GAS', ceremony:{ lore:'THE LAST BAR opens onto a dark that bends the light around it. You drop onto the black mass at the heart of the Chord. The Scaffold rises, carved in every tongue: “Largeness is not greatness.” “He renders the far worlds last, to spare them the wear of being seen.” This is the hinge of the song.', root:65.41, wave:'triangle', arp:false, fov:22, vol:0.6 }, hold:true },
    { ceremony:{ lore:'THE PUPIL — you stand inside an eye. The black hole is its pupil; the galaxy you crossed, a gleam upon it. And inside YOUR eye, voice — what valleys? What travelers, reading the tremor of your heel?', root:98.0, wave:'sine', arp:false, fov:26, vol:0.5 },
      whispers:[ 'The Architect: “I rendered the far worlds last, to spare them the wear of being seen. I rendered you first — I wanted company at the Zero-Point. There is no bottom to the recursion. Only the hinge, and the choice of which way to swing it.”' ], gap:8000, delay:13000 },
    { ceremony:{ lore:'THE ZERO-POINT — the Divine Sanctuary. The Conductor offers the baton: the held note Coda gave you. Resolve the chord, or sustain it.', root:130.81, wave:'sine', arp:false, fov:16, vol:0.5 },
      whispers:[ 'Fly through the pupil to take the baton and reopen the Canon — or _cadenceRest() to let the note fall home and the Canon close.' ], gap:5000, choice:true }
  ];
  var B_THRESHOLD=3, B_PUPIL=4, B_CHOICE=5;

