  function driftSettlement(sk, folk) {
    const m = memLoad(); const pk = planetKey();
    const now = Date.now();
    const last = m.visits[pk] || 0;
    m.visits[pk] = now;
    if (!last || folk.length < 2) { memSave(); return; }
    let buckets = Math.min(120, Math.floor((now - last) / (6 * 3600 * 1000)));   // up to ~30 days of history
    if (buckets <= 0) { memSave(); return; }
    const rng = mkRng(h32(pk + ':' + Math.floor(last / 1000)));
    while (buckets-- > 0) {
      // ~1 in 4 events are settlement-wide flavor rather than a pair event
      if (rng() < 0.25) { chronPush(sk, pick(rng, NEWS_TOWN)); continue; }
      const a = folk[Math.floor(rng() * folk.length)];
      let b = folk[Math.floor(rng() * folk.length)];
      if (a === b) b = folk[(folk.indexOf(a) + 1) % folk.length];
      const e = edgeFor(a.id, a.creed, b.id, b.creed);
      const A = first(a.name), B = first(b.name);
      const fill = function (s) { return s.replace('{A}', A).replace('{B}', B); };
      if (e.v <= -3.5 && rng() < 0.15) {            // rare reconciliation pulls a rift back
        e.v = -1.5; e.news = fill(pick(rng, NEWS_RECON)); chronPush(sk, e.news); continue;
      }
      const up = rng() < 0.5 + 0.22 * Math.sign(baseLean(a.creed, b.creed)) + 0.08 * Math.sign(e.v);
      e.v = Math.max(-4, Math.min(4, e.v + (up ? 0.7 : -0.7)));
      if (e.v >= 3.5 && !e.wed) { e.wed = true; e.news = fill(pick(rng, NEWS_WED)); chronPush(sk, e.news); continue; }
      if (e.v <= -3.5) { e.news = fill(pick(rng, NEWS_RIFT)); chronPush(sk, e.news); continue; }
      e.news = fill(up ? pick(rng, NEWS_UP) : pick(rng, NEWS_DOWN));
      if (rng() < 0.5) chronPush(sk, e.news);
    }
    memSave();
  }

