function topicFor(text){const t=clean(text,240).toLowerCase();if(/\b(bye|goodbye|farewell|see you)\b/.test(t))return 'bye';if(/\b(take your time|sorry|reassur|comfort|thank|are you okay)\b/.test(t))return 'kind';if(/\b(music|sing|song|bard|listen|instrument|jam|play|solo|rhythm)\b/.test(t))return 'music';if(/\b(weather|rain|storm|sunny)\b/.test(t))return 'weather';if(/\b(feel|feeling|angry|happy|sad|mood|how are you|what happened)\b/.test(t))return 'feeling';if(/\b(past|history|grew|family|story|stories|remember)\b/.test(t))return 'history';if(/\b(work|job|doing|purpose|occupation)\b/.test(t))return 'work';if(/\b(where|place|town|village|cave|planet|live)\b/.test(t))return 'place';if(/\b(help|need|quest|request)\b/.test(t))return 'help';if(/\b(hi|hello|hey|name)\b/.test(t))return 'greet';return 'unknown';}
